{code:java}private int writeTargets(DeploymentModel deploymentModel, LocalDateTime effectiveTime, int targetStep) {
    AtomicInteger counter = new AtomicInteger();
    DeploymentTemplateModel template = centralDeploymentsService.getDeploymentTemplate(deploymentModel.getTemplateId());
    if (template != null && CollectionUtils.isNotEmpty(template.getSteps()) && targetStep < template.getSteps().size()) {
        // ← Get the forceInstall flag from the template step
        boolean forceInstall = template.getSteps().get(targetStep).isForceInstall();

        List<InstallGroupModel> groups = template.getSteps().get(targetStep).getStoreGroups();
        groups.forEach(group -> {
            counter.getAndIncrement();
            clearTargetVersions(group, deploymentModel.getPackageName());
            updateManagementService.assignVersion(AssignVersionRequest.builder()
                    .version(deploymentModel.getVersion())
                    .groupId(group.getGroupId())
                    .effectiveDate(effectiveTime)
                    .packageName(deploymentModel.getPackageName())
                    .force(forceInstall)  // ← ADD THIS
                    .build());
        });
    } else {
        String deploymentName = deploymentModel.getDeploymentName() != null ? deploymentModel.getDeploymentName() : "[Unknown]";
        log.info("No template found for '" + deploymentName + "', template has no steps, or the provided step index of '" + targetStep + "' was out of bounds. Unable to write out install targets");
    }
    return counter.get();
}{code}

