private Map<String, Object> makeYmlMap(ConfigModel configModel, boolean logYamlLoadError) {
    Map<String, Object> yml = null;
    if (configModel != null && configModel.getConfigValue() != null) {
        String configValue = configModel.getConfigValue().trim();
        // Check for null string or empty value - return empty map to allow fallback to defaults
        if (configValue.isEmpty() || "null".equalsIgnoreCase(configValue)) {
            if (logYamlLoadError) {
                log.warn("Configuration '{}' has null or empty value in database, will use application.yml default", 
                    configModel.getConfigName());
            }
            return new LinkedHashMap<>();
        }

        Yaml ymlParser = new Yaml();
        try {
            yml = ymlParser.load(configValue);
        } catch (Exception e) {
            if (logYamlLoadError) {
                log.error("Error while parsing yml config value from database for '{}':\n{}", 
