/**
 * Determines if a transaction should be published to downstream systems.
 * Transactions in error/incomplete states should not be published to avoid duplicates.
 */
private boolean shouldPublishTransaction(TransModel transaction) {
    // Allow configuration override for special cases
    if (!contextService.getBoolean("openpos.publishing.suppressErrorStates", true)) {
        return true;
    }

    TransStatusCode status = transaction.getTransStatusCode();

    // Don't publish error/incomplete states
    if (status == TransStatusCode.ORPHANED || status == TransStatusCode.FAILED) {
        log.debug("Suppressing publish for transaction {} with status {}", 
            transaction.getTransKey(), status);
        return false;
    }

    // CANCELLED is publishable only if it's a legitimate cancellation (not a placeholder)
    // Placeholder transactions have minimal data - check for missing critical fields
    if (status == TransStatusCode.CANCELLED && isPlaceholderTransaction(transaction)) {
        log.debug("Suppressing publish for placeholder CANCELLED transaction {}", 
            transaction.getTransKey());
        return false;
    }

    return true;
}

private boolean isPlaceholderTransaction(TransModel transaction) {
    // Placeholder transactions have minimal data - check for missing critical fields
    return transaction.getBeginTime() == null || 
           transaction.getEndTime() == null ||
           (transaction instanceof RetailTransModel && 
            ((RetailTransModel)transaction).getRetailLineItems().isEmpty());
}{code}

