package org.jumpmind.pos.sales.service;

import lombok.extern.slf4j.Slf4j;
import org.jumpmind.pos.context.service.IContextService;
import org.jumpmind.pos.sales.model.RetailTransModel;
import org.jumpmind.pos.sales.model.TransModel;
import org.jumpmind.pos.sales.model.TransStatusCode;
import org.jumpmind.pos.sales.service.trans.model.SaveTransListenerException;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

@Slf4j
@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class PublishSuppressionSaveTransListener implements ISaveTransListener {

    @Autowired
    private IContextService contextService;

    @Override
    public void beforeSave(TransModel trans) throws SaveTransListenerException {
        if (contextService.getBoolean("openpos.publishing.suppressErrorStates", true)) {
            TransStatusCode status = trans.getTransStatusCode();

            if (status == TransStatusCode.ORPHANED || status == TransStatusCode.FAILED) {
                trans.setSuppressPublish(true);
                log.debug("Marking transaction {} for publish suppression due to status {}", 
                    trans.getTransKey(), status);
            }

            if (status == TransStatusCode.CANCELLED && isPlaceholderTransaction(trans)) {
                trans.setSuppressPublish(true);
                log.debug("Marking placeholder CANCELLED transaction {} for publish suppression", 
                    trans.getTransKey());
            }
        }
    }

    private boolean isPlaceholderTransaction(TransModel transaction) {
        return transaction.getBeginTime() == null || 
               transaction.getEndTime() == null ||
               (transaction instanceof RetailTransModel && 
                ((RetailTransModel)transaction).getRetailLineItems().isEmpty());
    }

    @Override
    public boolean shouldInvoke(TransModel transModel) {
        return true;
    }
}{code}

