{noformat}import { inject, Injectable } from '@angular/core';
import { catchError, concatMap, filter, map, of } from 'rxjs';
import {
  Print,
  PRINTERS_STATE_TOKEN,
  RegisteredPrinters,
} from './printing.symbols';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Actions, ofActionSuccessful, Store } from '@ngxs/store';
import { ScreenAction } from '@jmc/framework/screen-actions'; // ADD THIS IMPORT
import { MicroCapAware } from '@jmc/framework/micro-cap'; // ADD THIS IMPORT

/**
 * Service that will listen for print actions and find the printer associated
 * with the print request. It will then call the printer's print method with the
 * print request supplied.
 */
@Injectable({
  providedIn: 'root',
})
export class PrintListenerService {
  constructor() {
    const store = inject(Store);

    inject(Actions)
      .pipe(
        ofActionSuccessful(Print),
        map(
          (print) =>
            [print, store.selectSnapshot(PRINTERS_STATE_TOKEN)] as [
              Print,
              RegisteredPrinters,
            ],
        ),
        filter(([{ payload }]) => !!payload?.data),
        map(([{ payload: printRequest }, { defaultPrinter, printers }]) => {
          const printerType = printRequest.printerType ?? defaultPrinter;
          const printer = printerType ? printers[printerType] : null;
          return {
            printRequest,
            printer,
          };
        }),
        filter(({ printRequest: { printerType }, printer }) => {
          const hasPrinter = !!printer;
          if (!hasPrinter) {
            console.warn(`No printer found for '${printerType}`);
          }
          return hasPrinter;
        }),
        concatMap(({ printRequest, printer }) =>
          printer!
            .print(printRequest)
            .then(() => ({
              message: `Printed successfully`,
              printRequest,
              err: null,
            }))
            .catch((err) => ({
              message: `Error while retrieving print request: ${err}`,
              printRequest,
              err,
            })),
        ),
        catchError((err) =>
          of({ message: 'Unable to print', printRequest: null, err }),
        ),
        takeUntilDestroyed(),
      )
      .subscribe(({ message, printRequest, err }) => {
        console.log(`Print response: ${message}`, printRequest, err);

        // ADD THIS LOGIC TO DISPATCH ACTION:
        const actionName = err ? 'PrintError' : 'PrintNextDocument';
        // Get the microCapId from the printRequest (added by websocket.service.ts messageToAction)
        const connectionId = (printRequest as MicroCapAware<typeof printRequest>)?.__microCapId;

        if (connectionId) {
          store.dispatch(
            new ScreenAction(connectionId, {
              name: actionName,
              data: null,
              type: 'Screen',
              doNotBlockForResponse: true,
            })
          ).subscribe({
            next: () => console.log(`${actionName} action dispatched successfully`),
            error: (error) => console.error(`Error dispatching ${actionName} action:`, error),
          });
        } else {
          console.warn('No connectionId available for print response action');
        }
      });
  }
}{noformat}

