public CustomerModel getLinkedCustomerWithRetry() {
    CustomerModel customer = null;
    int retries = 3;
    int delayMs = 50;

    while (customer == null && retries > 0) {
        try {
            // Attempt to get customer from session
            if (transMgmtClient.isTransactionActive()) {
                customer = transMgmtClient.getLinkedCustomer();
            }

            if (customer == null && retries > 1) {
                Thread.sleep(delayMs);
                retries--;
            } else {
                break;
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            log.warn("Interrupted while waiting for session state", e);
            break;
        }
    }

    if (customer == null) {
