{code:java}package org.jumpmind.pos.sales.model;

import org.joda.money.Money;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

import static java.math.BigDecimal.ZERO;
import static org.jumpmind.pos.util.MoneyCalculator.zero;

/**
 * Aggregates all taxes into a single "Tax" line for simplified receipt display.
 * Use this aggregator when detailed tax breakdown is not required on receipts.
 * 
 * Configure via: openpos.sell.taxAggregator=simpleTaxAggregator
 */
@Component("simpleTaxAggregator")
public class SimpleTaxAggregator implements ITaxAggregator {

    @Override
    public List<TaxAggregate> aggregateTaxes(
            List<? extends ITaxGroupLineItem> taxGroupLineItems, 
            String isoCurrencyCode) {

        if (taxGroupLineItems == null || taxGroupLineItems.isEmpty()) {
            return List.of();
        }

        // Sum all non-voided tax amounts
        BigDecimal totalTaxAmount = taxGroupLineItems.stream()
                .filter(item -> !item.isVoided())
                .map(ITaxGroupLineItem::getTaxAmount)
                .filter(Objects::nonNull)
                .reduce(ZERO, BigDecimal::add);

        Money totalMoneyTaxAmount = taxGroupLineItems.stream()
                .filter(item -> !item.isVoided())
                .map(ITaxGroupLineItem::getMoneyTaxAmount)
                .filter(Objects::nonNull)
                .reduce(zero(isoCurrencyCode), Money::plus);

        // Return empty list if no tax
        if (totalTaxAmount.compareTo(ZERO) == 0) {
            return List.of();
        }

        // Create single tax aggregate with empty rule name
        // Template will display as "Tax    $X.XX"
        TaxAggregate aggregate = TaxAggregate.builder()
                .authorityId("total")
                .ruleName("")  // Empty - template shows "Tax" prefix only
                .ruleDescription("Total Tax")
                .totalAmount(totalTaxAmount)
                .totalMoneyAmount(totalMoneyTaxAmount)
                .build();

        return List.of(aggregate);
    }
}{code}

