private boolean hasBogoPromotion(RetailLineItemModel lineItem) {
    return lineItem.getPriceModifiers().stream()
        .anyMatch(pm -> pm.getModByAmount() != null 
            && pm.getModByAmount().equals(pm.getModificationTotal())
            && pm.getModificationTotal().isPositive());
