// Helper method to find the partner item in a BOGO pair
private RetailLineItemModel findBogoPartnerItem(RetailTransModel transaction, RetailLineItemModel freeItem) {
    // Find items with matching promotion that have non-zero value
    return transaction.getRetailLineItems().stream()
        .filter(li -> li.getLineSequenceNumber() != freeItem.getLineSequenceNumber())
        .filter(li -> li.getRtnExtendedDiscountedAmount() != null && !li.getRtnExtendedDiscountedAmount().isZero())
        .filter(li -> sharesBogoPromotion(li, freeItem))
        .findFirst()
        .orElse(null);
}

private boolean sharesBogoPromotion(RetailLineItemModel item1, RetailLineItemModel item2) {
    Set<String> promoIds1 = item1.getPriceModifiers().stream()
        .map(RetailLineItemPriceModifierModel::getPromotionId)
        .collect(Collectors.toSet());
    return item2.getPriceModifiers().stream()
        .anyMatch(pm -> promoIds1.contains(pm.getPromotionId()));
