h3. Option 1: Transaction Lifecycle Listener (RECOMMENDED)

*Risk:* Very Low | *Effort:* 2-3 hours

Implement {{IFinalizeSaleSessionListener}} to persist custom transaction data during transaction finalization.

*Pros:*

* Non-invasive: doesn't modify core framework code
* Multiple listeners can coexist independently
* Clear separation of concerns
* Easy to test in isolation
* Follows Spring's event-driven architecture
* Can be enabled/disabled via configuration
* Exception handling built-in

*Cons:*

* Executes synchronously (performance consideration)
* Must handle errors gracefully
* Executes before final save, so transaction not yet committed

*Implementation:*

{code:java}// File: src/main/java/com/landmarkgroup/pos/listener/CustomTransactionDataFinalizer.java
@Component
@Slf4j
public class CustomTransactionDataFinalizer implements IFinalizeSaleSessionListener {

    @Autowired
    private CustomTenderRepository customTenderRepository;

    @Autowired
    private CustomLineItemRepository customLineItemRepository;

    @Override
    public void finalizeSaleSession(SaleSession saleSession) {
        try {
            RetailTransModel transaction = saleSession.getActiveTransaction();

            // Persist tender-specific details
            transaction.getAllTenderLineItems().forEach(tender -> {
                CustomTenderDetail detail = CustomTenderDetail.builder()
                    .transactionKey(transaction.getTransKey())
                    .tenderCode(tender.getTenderCode())
                    .tenderAmount(tender.getTenderAmount())
                    .customField1(tender.getAdditionalFields().get("customField1"))
                    .build();
                customTenderRepository.save(detail);
            });

            // Persist sale line-item information
            transaction.getRetailLineItems().forEach(lineItem -> {
                CustomLineItemDetail detail = CustomLineItemDetail.builder()
                    .transactionKey(transaction.getTransKey())
                    .itemId(lineItem.getItemId())
                    .quantity(lineItem.getQuantity())
                    .customAttribute(lineItem.getAdditionalFields().get("customAttr"))
                    .build();
                customLineItemRepository.save(detail);
            });

        } catch (Exception e) {
            log.error("Failed to persist custom transaction data for transaction {}", 
                saleSession.getActiveTransaction().getTransKey(), e);
            // Don't rethrow - allow transaction to complete
        }
    }

    @Override
    public boolean shouldInvoke(SaleSession saleSession) {
        // Only run for completed transactions
        return TransStatusCode.COMPLETED.equals(
            saleSession.getActiveTransaction().getTransStatusCode());
    }
}{code}

