public class CustomTransactionDataPublisher implements ITransPublisher {

    @Autowired
    private CustomTenderRepository customTenderRepository;

    @Override
    public void publishTransaction(TransModel transaction) {
        if (!(transaction instanceof RetailTransModel)) {
            return;
        }

        RetailTransModel retailTrans = (RetailTransModel) transaction;

        try {
            log.info("Persisting custom data for transaction {}", transaction.getTransKey());

            retailTrans.getAllTenderLineItems().forEach(tender -> {
                customTenderRepository.save(buildCustomTenderDetail(tender, transaction));
            });

        } catch (Exception e) {
            log.error("Failed to publish custom transaction data", e);
        }
    }
}{code}

