{code:java}// File: symmetric-core/src/main/java/org/jumpmind/symmetric/service/impl/TriggerRouterService.java
protected void updateOrCreateDatabaseTriggers(final List<Trigger> triggers, final StringBuilder sqlBuffer, 
        final boolean force, final boolean verifyInDatabase, final List<TriggerHistory> activeTriggerHistories, 
        final boolean useTableCache, TriggerRouterContext triggerRouterContext) {

    // Add table existence check
    List<Trigger> validTriggers = new ArrayList<>();
    for (Trigger trigger : triggers) {
        Table table = symmetricDialect.getPlatform().getTableFromCache(
            trigger.getSourceCatalogName(),
            trigger.getSourceSchemaName(),
            trigger.getSourceTableName(),
            true);
        if (table != null) {
            validTriggers.add(trigger);
        } else {
            log.warn("Skipping trigger creation for non-existent table: {}", 
                trigger.qualifiedSourceTableName());
        }
    }

    Map<String, List<TriggerTableSupportingInfo>> triggerToTableSupportingInfo = 
        getTriggerToTableSupportingInfo(validTriggers, activeTriggerHistories, useTableCache, triggerRouterContext);

    int numThreads = getNumberOfThreadsToUseForSyncTriggers();
    ExecutorService executor = Executors.newFixedThreadPool(numThreads, new SyncTriggersThreadFactory());
    List<Future<?>> futures = new ArrayList<Future<?>>();

    for (final Trigger trigger : validTriggers) {
        Runnable task = new Runnable() {
            public void run() {
                MDC.put("engineName", parameterService.getEngineName());
                updateOrCreateDatabaseTrigger(trigger, triggers, sqlBuffer, force, 
                    verifyInDatabase, activeTriggerHistories, useTableCache, 
                    triggerToTableSupportingInfo, triggerRouterContext);
            }
        };
        futures.add(executor.submit(task));
    }
    awaitTermination(executor, futures);
}{code}

