protected void handleTableNotFound(Trigger trigger, List<TriggerHistory> activeTriggerHistories, TriggerRouterContext context) {
    log.warn("Table not found during trigger creation: {}", trigger.qualifiedSourceTableName());

    // Schedule retry after delay
    Thread retryThread = new Thread(() -> {
        try {
            Thread.sleep(30000); // Wait 30 seconds
            Table table = symmetricDialect.getPlatform().getTableFromCache(
                trigger.getSourceCatalogName(),
                trigger.getSourceSchemaName(),
                trigger.getSourceTableName(),
                true);
            if (table != null) {
                log.info("Table now exists, attempting trigger creation: {}", trigger.qualifiedSourceTableName());
                updateOrCreateDatabaseTriggers(Collections.singletonList(trigger), null, true, true, 
                    activeTriggerHistories, true, context);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    });
    retryThread.start();
