*IMPORTANT: This requires a code change in the idp-client library. The fix involves modifying `NoSecurityConfig` to use specific path matchers instead of matching all requests.*

h3. Step 1: Modify NoSecurityConfig with Specific Security Matcher

Restrict {{NoSecurityConfig}} to handle only specific paths ({{/idp/**}}, {{/actuator/**}}, {{/health}}) instead of all requests. This allows {{SecurityConfig}} to handle the remaining requests without conflict.

*File:* {{headless/core/idp-client/src/main/java/org/jumpmind/idp/NoSecurityConfig.java}} (in idp-client library)

*Updated Code:*

{code:java}package org.jumpmind.idp;

import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.annotation.Order;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
import org.springframework.security.config.annotation.web.configurers.HeadersConfigurer;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@ConditionalOnProperty(prefix = "secured.idp", name = "enabled", havingValue = "false", matchIfMissing = true)
public class NoSecurityConfig {

    @Bean
    @Order(1) // Ensure this runs before other security configs
    @ConditionalOnMissingBean(name = "noSecurityFilterChain")
    public SecurityFilterChain noSecurityFilterChain(HttpSecurity http) throws Exception {
        return http
                .securityMatcher("/idp/**", "/actuator/**", "/health", "/public/**")
                .csrf(AbstractHttpConfigurer::disable)
                .authorizeHttpRequests(auth -> auth.anyRequest().permitAll())
                .headers(headers -> headers.frameOptions(HeadersConfigurer.FrameOptionsConfig::sameOrigin))
                .build();
    }
}{code}

h3. Step 2: Ensure SecurityConfig Has Proper Order

*File:* {{org/jumpmind/commerce/central/server/auth/SecurityConfig.java}} (in commerce-central-server library)

{code:java}@Configuration
@ConditionalOnProperty(prefix = "secured.idp", name = "enabled", havingValue = "true")
public class SecurityConfig {

    @Bean
    @Order(2) // Ensure this runs after NoSecurityConfig
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        return http
                .securityMatcher("/**") // Catch-all for remaining requests
                .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
                .oauth2Login(Customizer.withDefaults())
                .oauth2ResourceServer(oauth2 -> oauth2.jwt(Customizer.withDefaults()))
                .build();
    }
