                if (this.modifyTransReponse.getSaleSession().getActiveTransaction().getActionsRequired() != null && ((String) this.modifyTransReponse.getSaleSession().getActiveTransaction().getActionsRequired().get(0)).startsWith("ManagerOverride")) {
                    this.modifyTransReponse = context.getTransMgmtClient().modifyTransaction(this.getAction(), modifyMethod, reasonCode, value, "Complete");
                    return true;
                } else {
                    return true;
                }
            } else if (action.getName().equals("ShowDiscountOptions")) {
                OptionsUIMessage screen = this.buildDiscountTypeOptionScreen(context);
                context.getUiManager().showScreen(screen);
                return false;
            } else {
                boolean showPromoRemoveWarning = !context.getTransMgmtClient().isManualTransDiscountStackableWithExistingItemsModifiers(context.getCurrentTransaction().getRetailLineItems());
