                    context.getUiManager().askYesNo("TransPromoRemoveWarningDialog", (String) null, "key:sale:handlers.screen.transdiscount.promoRemovalWarning.message", "ShowDiscountOptions", "Close");
                } else {
                    OptionsUIMessage screen = this.buildDiscountTypeOptionScreen(context);
                    context.getUiManager().showScreen(screen);
                }

                return false;
            }
        } else {
            return true;
        }
    }

    private OptionsUIMessage buildDiscountTypeOptionScreen(AppContext appContext) {
        OptionsUIMessage screen = new OptionsUIMessage();
        DialogHeaderPart dialogHeader = new DialogHeaderPart();
