    logger.info("Cancel was requested: {}", cardDataResult.getResultMessage() != null ? cardDataResult.getResultMessage() : cardDataResult.getResultCode());
    if (this.cardDetails.getEntryMode().equals(CardEntryMode.KEYED)
            && this.cardDetails.getTypeCode().equals(CardTypeCode.GIFTCARD)){
        doAction("GetCardDataSuccess");
    } else {
        cardDetails = null;
        doAction(CommonActionsConstants.BACK_ACTION);
    }{noformat}

